import { prisma } from "@/lib/prisma";
import { Metadata } from "next";
import Link from "next/link";

export const metadata: Metadata = {
    title: "Үйл ажиллагаа | МҮЗХ — 100 Жил",
    description: "Монголын Үндэсний Зуслангуудын Холбооны үйл ажиллагааны чиглэлүүд",
};

export const dynamic = "force-dynamic";

export default async function ActivitiesPage() {
    const categories = await prisma.activityCategory.findMany({
        orderBy: { order: "asc" },
        include: {
            items: {
                orderBy: { order: "asc" },
            },
        },
    });

    return (
        <div className="min-h-screen bg-slate-50 font-sans pb-24">
            {/* Navy Header Banner */}
            <div className="bg-[#0F1B3D] pt-20 pb-28 px-4 mb-20 relative overflow-hidden">
                {/* Decorative Blobs */}
                <div className="absolute top-0 right-0 w-80 h-80 bg-[#1A2B5C] rounded-full opacity-50 blur-[100px] -mr-32 -mt-32"></div>
                <div className="absolute bottom-0 left-0 w-64 h-64 bg-[#D4A843] rounded-full opacity-10 blur-[80px] -ml-20 -mb-20"></div>

                <div className="container mx-auto max-w-5xl text-center relative z-10">
                    <div className="inline-flex items-center rounded-full bg-[#F5C542]/20 border border-[#F5C542]/30 px-5 py-2 text-sm font-bold text-[#F5C542] mb-6 uppercase tracking-widest">
                        🚀 Үйл ажиллагаа
                    </div>
                    <h1 className="text-4xl md:text-6xl font-black text-white tracking-tight mb-6">
                        Манай <span className="text-[#F5C542]">Үндсэн Чиглэлүүд</span>
                    </h1>
                    <p className="text-lg md:text-xl text-white/60 max-w-2xl mx-auto font-medium">
                        МҮЗХ-ны хэрэгжүүлж буй үйл ажиллагааны үндсэн чиглэлүүд болон дэд хөтөлбөрүүд.
                    </p>
                </div>
            </div>

            {/* Categories */}
            <section className="container mx-auto px-4 max-w-6xl relative z-20 -mt-20">
                {categories.length === 0 ? (
                    <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200 shadow-sm">
                        <div className="text-5xl mb-6">🚀</div>
                        <p className="text-slate-500 text-lg font-medium">Одоогоор үйл ажиллагааны чиглэл нэмэгдээгүй байна.</p>
                    </div>
                ) : (
                    <div className="space-y-24">
                        {categories.map((cat, catIdx) => {
                            return (
                                <div key={cat.id} className="relative">
                                    {/* Category Header */}
                                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8 border-b-2 border-slate-200 pb-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-14 h-14 rounded-2xl bg-[#0F1B3D] text-[#F5C542] flex items-center justify-center font-black text-2xl shadow-lg ring-4 ring-[#0F1B3D]/5">
                                                {String(catIdx + 1).padStart(2, '0')}
                                            </div>
                                            <div>
                                                <h2 className="text-2xl md:text-3xl font-black text-[#0F1B3D] leading-tight">{cat.name}</h2>
                                                {cat.description && <p className="text-sm text-slate-500 mt-1 font-medium">{cat.description}</p>}
                                            </div>
                                        </div>
                                        <Link 
                                            href={`/activities/${cat.slug}`} 
                                            className="text-sm font-bold text-[#F5C542] bg-[#0F1B3D] hover:bg-[#1A2B5C] px-5 py-2 rounded-full transition-all"
                                        >
                                            Бүгдийг үзэх
                                        </Link>
                                    </div>

                                    {cat.items.length === 0 ? (
                                        <div className="text-slate-400 font-medium italic py-8 text-center bg-white rounded-2xl border border-dashed border-slate-200">
                                            Одоогоор энэ чиглэлээр нийтлэл нэмэгдээгүй байна.
                                        </div>
                                    ) : (
                                        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
                                            {cat.items.slice(0, 4).map(item => (
                                                <Link 
                                                    key={item.id} 
                                                    href={`/activities/${cat.slug}/${item.slug}`}
                                                    className="group bg-white rounded-2xl border border-slate-200 p-4 shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1 flex flex-col h-full"
                                                >
                                                    {item.imageUrl && (
                                                        <div className="aspect-video rounded-xl overflow-hidden mb-4 bg-slate-100">
                                                            <img src={item.imageUrl} alt={item.title} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                                                        </div>
                                                    )}
                                                    <div className="inline-block px-2.5 py-1 rounded-full text-[10px] font-bold mb-3 bg-[#F5C542]/10 text-[#0F1B3D] uppercase tracking-wider">
                                                        {cat.name}
                                                    </div>
                                                    <h3 className="font-bold text-[#0F1B3D] group-hover:text-blue-600 transition-colors line-clamp-2 text-sm leading-snug flex-grow">{item.title}</h3>
                                                    <div className="mt-4 flex items-center gap-1 text-[10px] font-bold text-[#D4A843] opacity-0 group-hover:opacity-100 transition-all">
                                                        Дэлгэрэнгүй <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7"/></svg>
                                                    </div>
                                                </Link>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </section>
        </div>
    );
}
